import json
from pathlib import Path
p=json.loads(Path('router/references/tools.json').read_text())
if isinstance(p,dict):
 print('keys:', list(p))
 tools=p.get('tools',[])
else: tools=p
if isinstance(tools,dict):
 for k,v in tools.items():
  if 'flute' in k.lower() or 'ffmpeg' in k.lower(): print(json.dumps({k:v},indent=2))
else:
 for t in tools:
  if 'flute' in str(t.get('id','')).lower() or 'ffmpeg' in str(t.get('id','')).lower(): print(json.dumps(t,indent=2))
